&lt;p data-local-id=&quot;6eec2e33e528&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;paragraph&quot; data-prosemirror-node-block=&quot;true&quot;&gt;&lt;strong data-prosemirror-content-type=&quot;mark&quot; data-prosemirror-mark-name=&quot;strong&quot;&gt;&lt;span id=&quot;593fdcfc-f494-4007-b1ec-a0faf4bbece8&quot; data-mark-type=&quot;annotation&quot; data-mark-annotation-type=&quot;inlineComment&quot; data-id=&quot;593fdcfc-f494-4007-b1ec-a0faf4bbece8&quot; data-prosemirror-content-type=&quot;mark&quot; data-prosemirror-mark-name=&quot;annotation&quot;&gt;Reporting to leadership&lt;/span&gt;:&lt;/strong&gt; Providing regular project status updates to Employee Enablement leadership covering progress, risks, issues, financials, and milestones — keeping reporting aligned with broader programme governance standards.&lt;/p&gt;
